const $=s=>document.querySelector(s);let cfg,ref,target,sourceImage,registered=true,mode=null,start=null,worker=null,timer,busy=false,result=null,urls=[],baselineReady=true;
const messages={restored:['배치 완료 · 검토 필요','원본 인쇄를 배치했습니다. 문구가 정확히 읽히는지, 경계가 자연스러운지 확인하세요.'],preserve_existing_ink:['기존 인쇄 유지','해당 위치에 인쇄가 있어 변경하지 않았습니다. 문구 내용까지 맞는지 확인한 것은 아닙니다.'],abstain_small_text:['보류 · 작은 인쇄','글자가 너무 작습니다. 제품 크기를 바꿔도 되는 요청에서만 큰 라벨 광고를 다시 준비하세요.'],abstain_alignment:['보류 · 위치 근거 부족','문구 주변 대응점을 충분히 확보하지 못했습니다. 결과 위치를 임의로 맞추지 않고 입력을 유지했습니다.'],abstain_ambiguous_ink:['보류 · 빈 영역 불확실','기존 인쇄나 배경 무늬가 감지되어 중복 인쇄를 피하기 위해 보류했습니다.']};
function status(t){$('#status').textContent=t}function clearResult(){result=null;$('#ours').src='assets/success.png';$('#oursLabel').textContent='Run 25 보관 결과 · 현재 입력은 아직 처리하지 않음';$('#download').disabled=$('#report').disabled=true;$('#metrics').replaceChildren();$('#showBefore').click();$('#message').textContent='입력을 바꿨습니다. 자동 배치를 다시 실행하세요.'}
function objurl(bytes){const u=URL.createObjectURL(new Blob([bytes],{type:'image/png'}));urls.push(u);return u}
async function readImage(input){if(input instanceof File&&input.size>12*1024*1024)throw Error('파일은 12MB 이하로 준비해 주세요.');const blob=input instanceof Blob?input:await(await fetch(input)).blob();const im=await createImageBitmap(blob);if(im.width*im.height>24000000){im.close();throw Error('이미지가 너무 큽니다. 24메가픽셀 이하로 줄여 주세요.')}const scale=Math.min(1,1024/Math.max(im.width,im.height));const c=document.createElement('canvas');c.width=Math.round(im.width*scale);c.height=Math.round(im.height*scale);c.getContext('2d').drawImage(im,0,0,c.width,c.height);im.close();const png=await new Promise(r=>c.toBlob(r,'image/png'));return {bytes:await png.arrayBuffer(),canvas:c,url:URL.createObjectURL(png)}}
function draw(){const c=$('#sourceCanvas');c.width=sourceImage.width;c.height=sourceImage.height;let ctx=c.getContext('2d');ctx.drawImage(sourceImage,0,0);ctx.lineWidth=4;ctx.strokeStyle='#18764e';ctx.beginPath();cfg.source_label_quad.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.stroke();ctx.strokeStyle='#d24d16';const r=cfg.source_text_roi;ctx.strokeRect(r[0],r[1],r[2]-r[0],r[3]-r[1]);}
function coords(){const q=cfg.source_label_quad;$('#labelCoords').value=[Math.min(...q.map(p=>p[0])),Math.min(...q.map(p=>p[1])),Math.max(...q.map(p=>p[0])),Math.max(...q.map(p=>p[1]))].join(',');$('#textCoords').value=cfg.source_text_roi.join(',')}
function markUnregistered(){registered=false;$('#registration').textContent='영역 확인 후 원본 등록 완료를 누르세요.';clearResult()}
function rectValid(r){return r.length===4&&r.every(Number.isFinite)&&r[0]>=0&&r[1]>=0&&r[2]<=sourceImage.width&&r[3]<=sourceImage.height&&r[2]-r[0]>=8&&r[3]-r[1]>=8}
function setRect(r){if(!rectValid(r))throw Error('영역은 사진 안에서 가로·세로 8px 이상이어야 합니다.');if(mode==='label')cfg.source_label_quad=[[r[0],r[1]],[r[2],r[1]],[r[2],r[3]],[r[0],r[3]]];else cfg.source_text_roi=r;coords();draw();markUnregistered()}
$('#labelMode').onclick=()=>{mode='label';$('#registration').textContent='라벨 전체 영역을 드래그하세요.'};$('#textMode').onclick=()=>{mode='text';$('#registration').textContent='검은 제품명 한 줄만 드래그하세요.'};
const c=$('#sourceCanvas');function point(e){const r=c.getBoundingClientRect();return [Math.max(0,Math.min(c.width,Math.round((e.clientX-r.left)*c.width/r.width))),Math.max(0,Math.min(c.height,Math.round((e.clientY-r.top)*c.height/r.height)))]}
c.onpointerdown=e=>{if(mode&&!busy){start=point(e);c.setPointerCapture(e.pointerId)}};c.onpointerup=e=>{if(!start)return;const p=point(e);try{setRect([Math.min(p[0],start[0]),Math.min(p[1],start[1]),Math.max(p[0],start[0]),Math.max(p[1],start[1])])}catch(e){$('#registration').textContent=e.message}start=null};
$('#coordsApply').onclick=()=>{try{const a=$('#labelCoords').value.split(',').map(Number),b=$('#textCoords').value.split(',').map(Number);if(!rectValid(a)||!rectValid(b))throw Error('유효한 영역 좌표를 입력하세요.');cfg.source_label_quad=[[a[0],a[1]],[a[2],a[1]],[a[2],a[3]],[a[0],a[3]]];cfg.source_text_roi=b;draw();markUnregistered()}catch(e){$('#registration').textContent=e.message}};
$('#register').onclick=()=>{const r=cfg.source_text_roi,q=cfg.source_label_quad;if(!rectValid(r)||r[0]<Math.min(...q.map(x=>x[0]))||r[2]>Math.max(...q.map(x=>x[0]))||r[1]<Math.min(...q.map(x=>x[1]))||r[3]>Math.max(...q.map(x=>x[1]))){$('#registration').textContent='제품명 영역이 라벨 안에 들어가도록 확인하세요.';return}cfg.presence_guard_roi=[Math.max(0,r[0]-13),Math.max(0,r[1]-8),Math.min(sourceImage.width,r[2]+15),Math.min(sourceImage.height,r[3]+15)];registered=true;mode=null;$('#registration').textContent='원본 등록 완료 · 현재 브라우저에서만 유지됩니다.'};
async function loadSample(){if(busy)return;cfg=await(await fetch('assets/config.json')).json();ref=await readImage('assets/reference.webp');sourceImage=ref.canvas;target=await readImage('assets/'+$('#sample').value+'.png');registered=true;$('#sourceFile').value=$('#targetFile').value='';$('#confirm').checked=true;coords();draw();clearResult();$('#preview').src=target.url;$('#registration').textContent='기본 원본 등록됨';status('입력 준비')}
$('#load').onclick=()=>loadSample().catch(error);$('#reset').onclick=()=>{cancel();urls.forEach(URL.revokeObjectURL);urls=[];$('#sample').value='large';$('#baselineFile').value='';$('#baseline').src='assets/direct.png';$('#baseline').hidden=false;baselineReady=true;$('#baselineLabel').textContent='직접 생성 1회 · 후처리 없음';$('#ours').src='assets/success.png';$('#oursLabel').textContent='Run 25 보관 결과';loadSample().catch(error)};
function error(e){status('처리 오류');$('#message').textContent=String(e.message||e)+' 입력 파일과 네트워크 상태를 확인한 뒤 다시 시도하세요.'}
$('#sourceFile').onchange=async e=>{try{if(!e.target.files[0])return;ref=await readImage(e.target.files[0]);sourceImage=ref.canvas;cfg.source_label_quad=[[0,0],[sourceImage.width,0],[sourceImage.width,sourceImage.height],[0,sourceImage.height]];cfg.source_text_roi=[0,0,0,0];coords();draw();markUnregistered()}catch(e){error(e)}};
$('#targetFile').onchange=async e=>{try{if(!e.target.files[0])return;target=await readImage(e.target.files[0]);clearResult();$('#preview').src=target.url;status('입력 준비')}catch(e){error(e)}};
function lock(v){busy=v;document.querySelectorAll('aside button,aside input,aside select,.toolbar button,.toolbar select').forEach(x=>x.disabled=v);$('#cancel').disabled=false;$('#cancel').hidden=!v}
function cancel(){worker?.terminate();worker=null;clearTimeout(timer);lock(false);status('처리 취소');}
$('#cancel').onclick=cancel;
$('#run').onclick=()=>{if(!cfg||!ref||!target){error(Error('입력을 불러오는 중입니다. 잠시 후 다시 시도해 주세요.'));return}if(!registered){error(Error('먼저 원본 영역을 등록하세요.'));return}if(!$('#confirm').checked){error(Error('지원 범위는 같은 JamMate 상품입니다. 동일 상품 여부를 확인하세요.'));return}clearResult();lock(true);const t=performance.now();worker??=new Worker('worker.js');timer=setTimeout(()=>{cancel();error(Error('처리 시간이 3분을 초과했습니다. 다시 시도해 주세요.'))},180000);worker.onerror=e=>{cancel();error(Error(e.message))};worker.onmessage=({data:d})=>{if(d.stage){status(d.stage);return}clearTimeout(timer);lock(false);if(d.error){worker.terminate();worker=null;error(Error(d.error));return}result={...d,seconds:(performance.now()-t)/1000,url:objurl(d.out),maskurl:objurl(d.mask)};const [s,m]=messages[d.report.decision]||['보류','입력을 유지했습니다.'];status(s);$('#message').textContent=m;$('#metrics').replaceChildren();Object.entries({'인쇄 영역 높이':d.report.ink_height+'px','변경 픽셀':d.report.changed_pixels+'px','영역 밖 변경':d.report.changed_outside_support+'px','이번 처리 시간':result.seconds.toFixed(1)+'초 (최초 로딩 포함)','문구 위/아래 대응점':(d.report.inliers_above_below_name||[0,0]).join(' / ')}).forEach(([k,v])=>{const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=k;dd.textContent=v;$('#metrics').append(dt,dd)});$('#download').disabled=$('#report').disabled=false;$('#showAfter').click();$('#ours').src=result.url;$('#oursLabel').textContent='현재 처리 결과 · '+s};worker.postMessage({cfg:structuredClone(cfg),ref:ref.bytes.slice(0),target:target.bytes.slice(0)})};
function view(which){document.querySelectorAll('.views button').forEach(b=>b.setAttribute('aria-pressed',b.id===which));$('#preview').src=which==='showBefore'?target?.url:which==='showAfter'?result?.url||target?.url:result?.maskurl||target?.url}
['showBefore','showAfter','showMask'].forEach(id=>$('#'+id).onclick=()=>view(id));function download(data,name,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
$('#download').onclick=()=>download(result.out,'jammate-'+result.report.decision+'.png','image/png');$('#report').onclick=()=>download(JSON.stringify({...result.report,browser_seconds:result.seconds},null,2),'jammate-report.json','application/json');
$('#copyPrompt').onclick=async()=>{try{await navigator.clipboard.writeText($('#prompt').value);$('#copyPrompt').textContent='복사됨'}catch{ $('#prompt').select();$('#copyPrompt').textContent='텍스트를 선택했습니다. 복사해 주세요.'}};
$('#baselineFile').onchange=async e=>{try{if(!e.target.files[0])return;const x=await readImage(e.target.files[0]);$('#baseline').src=x.url;$('#baseline').hidden=false;baselineReady=true;$('#baselineLabel').textContent='사용자 제공 직접 호출 결과 · 모델/조건 미확인'}catch(e){error(e)}};
$('#compareDownload').onclick=()=>download(JSON.stringify({baseline_provided:baselineReady,baseline_label:$('#baselineLabel').textContent,ours_label:$('#oursLabel').textContent,ours:result?.report||'Run25 archived result',human_readability:$('#readability').value,notes:$('#notes').value,warning:'사용자 시각 비교. 동일 조건 대조 실험 아님. 자동 우월성 점수 없음'},null,2),'comparison-notes.json','application/json');
const runs=[['19','원본 재투영','넓은 평면은 유망했지만, 6개 목표 시점 중 모든 항목을 통과한 시점은 없었습니다. 모서리·접합부 오류가 남았습니다.','구조 정확도 미통과'],['20','정답 없이 구도 선택','18°를 사전 선택했습니다. 기준 33°보다 로고는 좋아졌지만 접합선은 악화됐습니다.','선택 규칙 보류'],['21','제작 실사의 구조 신호 추가','기존·새 점수 모두 21°를 선택했습니다. 한 번의 수정으로 개선이 없어 점수 조정을 중단했습니다.','분기 종료'],['22','표면만 원본으로 복원','누락 제품명을 수동 위치 지정으로 옮겼고 편집 영역 밖 변화는 없었습니다. 자동화는 미검증이었습니다.','좁은 가능성'],['23','자동 위치 추정','실제 누락 1건과 통제 누락 1건에서 자동 배치. 정상 대조군 유지. 작은 8px 글자는 가독성이 부족했습니다.','조건부 진행'],['24','축소 방식 비교','4배 투영 후 축소로 획은 부드러워졌지만 실용적 가독성 개선은 불명확했습니다. 작은 인쇄 분기를 닫았습니다.','작은 라벨 제외'],['25','새 광고 제작 흐름','기존 등록값으로 새 광고에 25px 제품명을 배치했습니다. 전체 4분 57초, 결과 위치 수정 0회. 계획된 빈 영역이며 직접 호출 비교 실험은 아닙니다.','JamMate 큰 라벨 가능성'],['26','다른 상품 신규 등록','비락식혜 손글씨 영역 아래 대응점 0개로 보류. 신규 등록 1분 13초, 결과 문구 미복원. 일반 상품으로 확대하지 않았습니다.','탐색 종료']];
runs.forEach((r,i)=>{const b=document.createElement('button');b.textContent='Run '+r[0];b.onclick=()=>{document.querySelectorAll('#timeline button').forEach(x=>x.setAttribute('aria-pressed',x===b));$('#runDetail').replaceChildren();const h=document.createElement('h3'),p=document.createElement('p'),s=document.createElement('strong');h.textContent=r[1];p.textContent=r[2];s.textContent=r[3];$('#runDetail').append(h,s,p)};$('#timeline').append(b);if(i===6)b.click()});loadSample().catch(error);
